import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { emit } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as emailService from "@/server/services/email-service";
import { runDigestEmailJob } from "@/server/jobs/digest-email-job";
import { listNotifications, notify, muteProject, unmuteProject, listMutedProjectIds } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, ProjectId } from "@/types/common";

let cleanup: () => void;
let t: Tenant;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); t = await createTenant("mute", "growth"); });
afterAll(() => cleanup());

describe("mute", () => {
  it("guards", async () => {
    const other = await createTenant("mute-other", "growth");
    await expect(muteProject(other.actors.member, t.org.id, t.project.id)).rejects.toBeInstanceOf(TenantScopeError);
    await expect(muteProject(t.actors.member, t.org.id, "nope" as ProjectId)).rejects.toBeInstanceOf(NotFoundError);
    await expect(muteProject(t.actors.member, t.org.id, other.project.id)).rejects.toBeInstanceOf(NotFoundError);
    await muteProject(t.actors.viewer, t.org.id, t.project.id);
    await muteProject(t.actors.viewer, t.org.id, t.project.id);
    expect(await listMutedProjectIds(t.actors.viewer, t.org.id)).toEqual([t.project.id]);
    expect(await listMutedProjectIds(t.actors.admin, t.org.id)).toEqual([]);
    await unmuteProject(t.actors.viewer, t.org.id, t.project.id);
    await unmuteProject(t.actors.viewer, t.org.id, t.project.id);
    expect(await listMutedProjectIds(t.actors.viewer, t.org.id)).toEqual([]);
  });

  it("notify rules", async () => {
    await muteProject(t.actors.admin, t.org.id, t.project.id);
    const p = { title: "x", body: "x", href: "/x", actorId: null, projectId: t.project.id };
    const a = await notify(t.org.id, "issue_assigned", [t.userIds.admin, t.userIds.viewer], p);
    expect(a.find((r) => r.recipientId === t.userIds.admin)?.channels).toEqual(["in_app"]);
    expect(a.find((r) => r.recipientId === t.userIds.viewer)?.channels).toEqual(["in_app", "email"]);
    const b = await notify(t.org.id, "comment_created", [t.userIds.admin, t.userIds.viewer], p);
    expect(b.map((r) => r.recipientId)).toEqual([t.userIds.viewer]);
    const c = await notify(t.org.id, "member_joined", [t.userIds.admin], { ...p, projectId: null });
    expect(c).toHaveLength(1);
    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.admin, kind: "issue_overdue", inApp: false, email: true, digestOnly: false });
    const d = await notify(t.org.id, "issue_overdue", [t.userIds.admin], p);
    expect(d).toHaveLength(0);

    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.admin }));
    await emit("comment.created", { orgId: t.org.id, actorId: t.userIds.member, occurredAt: issue.createdAt, commentId: "c1" as CommentId, issueId: issue.id, mentionedUserIds: [t.userIds.admin] });
    const page = await listNotifications(t.actors.admin, { orgId: t.org.id, recipientId: t.userIds.admin, unreadOnly: false, kind: ["comment_created", "comment_mention", "issue_assigned"], limit: 50, cursor: null });
    const fromIssue = page.items.filter((n) => n.href === `/issues/${issue.id}`);
    console.log(fromIssue.map((n) => [n.kind, n.channels, n.projectId]));
    expect(fromIssue.some((n) => n.kind === "comment_created")).toBe(false);
    expect(fromIssue.find((n) => n.kind === "comment_mention")?.channels).toEqual(["in_app"]);
    await unmuteProject(t.actors.admin, t.org.id, t.project.id);
  });

  it("digest", async () => {
    const tt = await createTenant("mute-digest", "growth");
    await orgRepo.updateOrg(tt.org.id, { orgId: tt.org.id, settings: { digestHourUtc: 9 } });
    await usageRepo.recomputeUsage(tt.org.id);
    await preferenceRepo.upsertPreference({ orgId: tt.org.id, userId: tt.userIds.member, kind: "comment_created", inApp: false, email: false, digestOnly: true });
    const now = new Date();
    now.setUTCMinutes(now.getUTCMinutes() + 1);
    // hour
    await orgRepo.updateOrg(tt.org.id, { orgId: tt.org.id, settings: { digestHourUtc: now.getUTCHours() } });
    const p = { title: "about", body: "x", href: "/x", actorId: null, projectId: tt.project.id };
    await notify(tt.org.id, "issue_assigned", [tt.userIds.member], p);
    await muteProject(tt.actors.member, tt.org.id, tt.project.id);
    const spy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
    await runDigestEmailJob(now);
    expect(spy).not.toHaveBeenCalled();
    await unmuteProject(tt.actors.member, tt.org.id, tt.project.id);
    await runDigestEmailJob(now);
    expect(spy).toHaveBeenCalledTimes(1);
    await runDigestEmailJob(now);
    expect(spy).toHaveBeenCalledTimes(1);
  });
});
